changeSet.sql:

create unique clustered index UCI_CatalogBrowseSubject
ON dbo.CatalogBrowseSubject (IntersectId);

CREATE INDEX IX_CatalogBrowseSubject_DisplayValue
ON dbo.CatalogBrowseSubject (SubjectDisplayValue);

CREATE INDEX IX_CatalogBrowseSubject_PredicateId
ON dbo.CatalogBrowseSubject (PredicateId) include (SubjectDisplayValue);

CREATE INDEX IX_CatalogBrowseSubject_ObjectAssetId
ON dbo.CatalogBrowseSubject (ObjectAssetId);
